const phrases = $input.all().map(i => i.json).filter(r => r && r.phrase);
let entrySrc;
try { entrySrc = $('Mark Form Entry').first().json; } catch (e) { entrySrc = $('Mark Sub-Workflow Entry').first().json; }
const content = String(entrySrc.content || '');
const lower = content.toLowerCase();
let found = '';
for (const p of phrases) {
  if (lower.includes(String(p.phrase).toLowerCase())) { found = String(p.phrase); break; }
}
return [{ json: {
  entry: String(entrySrc.entry || 'subworkflow'),
  content: content,
  channel: String(entrySrc.channel || ''),
  phrases_loaded: phrases.length,
  found_phrase: found
} }];

