parameters.jsCode:
const scan = $('Scan For A Disclosure Phrase').first().json;
const first = $input.first();
const raw = first ? first.json : {};
const src = raw && typeof raw.output === 'object' && raw.output !== null ? raw.output : raw;
let note = 'Groq judged the clarity of the disclosure.';
let conf = Number(src ? src.confidence : NaN);
if (!Number.isFinite(conf)) { conf = 0; note = 'The model did not return a readable judgement; this verdict rests on the exact phrase match alone.'; }
if (conf > 0 && conf <= 1) { conf = Math.round(conf * 100); }
conf = Math.max(0, Math.min(100, Math.round(conf)));
const adequate = src && src.adequate === true;
const suggestion = String((src && src.suggestion) || '').slice(0, 300);
let verdict;
let refusal = '';
if (Number(scan.phrases_loaded) === 0) {
  verdict = 'MANUAL_REVIEW';
  refusal = 'The disclosure phrase table is empty, so nothing was actually checked. This checker refuses to answer without its reference phrases; a person must look at this piece.';
} else if (scan.found_phrase) {
  verdict = 'DISCLOSED';
} else if (adequate && conf >= 60) {
  verdict = 'DISCLOSED_UNLISTED';
  note += ' No listed phrase matched, but the model found a clear disclosure worded differently; consider adding that wording to your phrase table.';
} else {
  verdict = 'MISSING';
}
return [{ json: {
  entry: scan.entry,
  checked_at: new Date().toISOString(),
  channel: scan.channel,
  verdict: verdict,
  found_phrase: scan.found_phrase,
  model_adequate: adequate ? 'yes' : 'no',
  model_confidence: conf,
  suggestion: verdict === 'MISSING' ? (suggestion || 'This content was generated with AI.') : '',
  content_excerpt: String(scan.content).slice(0, 300),
  note: note + (refusal ? ' ' + refusal : '')
} }];

